mapper.select:
SELECT id, conversation_id, user_id, client_request_id, role, content, metadata_json, create_time
FROM chat_messages
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
ORDER BY create_time ASC, id ASC

SELECT id, conversation_id, user_id, client_request_id, role, content, metadata_json, create_time
FROM (
  SELECT id, conversation_id, user_id, client_request_id, role, content, metadata_json, create_time
  FROM chat_messages
  WHERE conversation_id = #{conversationId}
    AND user_id = #{userId}
  ORDER BY create_time DESC, id DESC
  LIMIT #{offset}, #{limit}
) page_messages
ORDER BY create_time ASC, id ASC

SELECT id, conversation_id, user_id, client_request_id, role, content, metadata_json, create_time
FROM (
    SELECT id, conversation_id, user_id, client_request_id, role, content, metadata_json, create_time
    FROM chat_messages
    WHERE conversation_id = #{conversationId}
      AND user_id = #{userId}
    ORDER BY create_time DESC, id DESC
    LIMIT #{limit}
) recent_messages
ORDER BY create_time ASC, id ASC

SELECT id, conversation_id, user_id, client_request_id, role, content, metadata_json, create_time
FROM chat_messages
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND client_request_id = #{clientRequestId}
  AND role = #{role}
ORDER BY id ASC
LIMIT 1

mapper.delete:
DELETE FROM chat_messages
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}

mapper.update:
UPDATE chat_messages
SET metadata_json = JSON_OBJECT('status', 'completed')
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND role = 'assistant'
  AND metadata_json IS NOT NULL
  AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.status')) = 'confirming'

    AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.confirm.interruptId')) = #{interruptId}

ORDER BY id DESC
LIMIT 1
